<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Support Contact Form</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #0b1020;
        --panel: rgba(15, 23, 42, 0.92);
        --panel-2: rgba(17, 24, 39, 0.9);
        --border: rgba(148, 163, 184, 0.18);
        --text: #e5e7eb;
        --muted: #94a3b8;
        --accent: #60a5fa;
        --accent-strong: #3b82f6;
        --danger: #f87171;
        --shadow: 0 24px 80px rgba(2, 6, 23, 0.55);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top, rgba(96, 165, 250, 0.18), transparent 30%),
          linear-gradient(180deg, #07111f 0%, #0b1020 48%, #050816 100%);
        color: var(--text);
        display: grid;
        place-items: center;
        padding: 32px 16px;
      }

      .page {
        width: min(100%, 760px);
      }

      .card {
        background: linear-gradient(180deg, rgba(15, 23, 42, 0.96), rgba(10, 15, 28, 0.96));
        border: 1px solid var(--border);
        box-shadow: var(--shadow);
        border-radius: 24px;
        overflow: hidden;
      }

      .hero {
        padding: 32px 32px 8px;
        background: linear-gradient(180deg, rgba(96, 165, 250, 0.08), transparent);
      }

      .eyebrow {
        color: var(--accent);
        font-size: 0.82rem;
        font-weight: 700;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        margin: 0 0 10px;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 4vw, 3rem);
        line-height: 1.05;
      }

      .subtitle {
        margin: 14px 0 0;
        max-width: 58ch;
        color: var(--muted);
        line-height: 1.6;
      }

      form {
        padding: 24px 32px 32px;
      }

      .form-grid {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 18px;
      }

      .form-field {
        display: flex;
        flex-direction: column;
        gap: 8px;
      }

      .form-field.full {
        grid-column: 1 / -1;
      }

      label {
        font-size: 0.95rem;
        font-weight: 600;
        color: #dbe4f0;
      }

      .required {
        color: var(--accent);
      }

      input {
        width: 100%;
        border: 1px solid rgba(148, 163, 184, 0.24);
        background: rgba(8, 12, 24, 0.9);
        color: var(--text);
        border-radius: 14px;
        padding: 14px 16px;
        font: inherit;
        outline: none;
        transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
      }

      input::placeholder {
        color: #64748b;
      }

      input:focus {
        border-color: rgba(96, 165, 250, 0.9);
        box-shadow: 0 0 0 4px rgba(59, 130, 246, 0.18);
      }

      input[aria-invalid="true"] {
        border-color: rgba(248, 113, 113, 0.75);
        box-shadow: 0 0 0 4px rgba(248, 113, 113, 0.12);
