        color: #bbf7d0;
        display: none;
      }

      .success.show {
        display: block;
      }

      @media (max-width: 640px) {
        .hero,
        form {
          padding-left: 20px;
          padding-right: 20px;
        }

        .form-grid {
          grid-template-columns: 1fr;
        }

        .actions {
          justify-content: stretch;
        }

        button {
          width: 100%;
        }
      }
    </style>
  </head>
  <body>
    <div id="app" class="page"></div>

    <script>
      const h = (tag, props = {}, ...children) => {
        const el = document.createElement(tag);
        for (const [key, value] of Object.entries(props)) {
          if (key === "className") el.className = value;
          else if (key === "textContent") el.textContent = value;
          else if (key.startsWith("on") && typeof value === "function") el.addEventListener(key.slice(2).toLowerCase(), value);
          else if (value !== false && value != null) el.setAttribute(key, value);
        }
        children.flat().forEach((child) => {
          if (child == null || child === false) return;
          el.appendChild(typeof child === "string" ? document.createTextNode(child) : child);
        });
        return el;
      };

      function Field({ id, label, type = "text", placeholder, required = false, helperText = "", errorText = "", value = "", className = "" }) {
        const input = h("input", {
          id,
          name: id,
          type,
          placeholder,
          value,
          "aria-invalid": errorText ? "true" : "false",
          "aria-describedby": helperText ? `${id}-help` : errorText ? `${id}-error` : undefined,
          required: required ? "required" : undefined,
        });

        return h(
          "div",
          { className: `form-field${className ? ` ${className}` : ""}` },
          h("label", { for: id }, label, required ? h("span", { className: "required", textContent: " *" }) : null),
          input,
          helperText ? h("div", { className: "helper", id: `${id}-help`, textContent: helperText }) : null,
          h("div", { className: "error", id: `${id}-error`, textContent: errorText || "" })
        );
      }

      function ContactForm() {
        const state = {
          submitted: false,
          values: { fullName: "", email: "", phone: "" },
        };

        const form = h("form", { novalidate: "novalidate" });
        const fullNameField = () =>
          Field({
            id: "fullName",
            label: "Full name",
            placeholder: "Jane Doe",
            required: true,
            value: state.values.fullName,
            errorText: state.submitted && !state.values.fullName.trim() ? "Please enter your full name." : "",
          });

        const emailField = () =>
          Field({
            id: "email",
            label: "Email address",
            type: "email",
            placeholder: "jane@company.com",
            required: true,
            value: state.values.email,
            errorText:
              state.submitted && !state.values.email.trim()
                ? "Please enter your email address."
                : state.submitted && form.elements.email && !form.elements.email.validity.valid
                ? "Please enter a valid email address."
                : "",
          });

        const phoneField = () =>
          Field({
            id: "phone",
            label: "Phone number",
            type: "tel",
            placeholder: "+1 555 123 4567",
            value: state.values.phone,
            helperText: "Optional. Use a format like +1 555 123 4567 or 555-123-4567.",
            className: "full",
          });

        const fields = h("div", { className: "form-grid" }, fullNameField(), emailField(), phoneField());
        const success = h("div", { className: "success", textContent: "Thanks — your message has been prepared for submission." });

        function renderFields() {
          fields.replaceChildren(fullNameField(), emailField(), phoneField());
        }

        form.addEventListener("submit", (event) => {
          event.preventDefault();
          state.submitted = true;
          state.values.fullName = form.elements.fullName.value;
          state.values.email = form.elements.email.value;
          state.values.phone = form.elements.phone.value;

          const valid = form.checkValidity();
          renderFields();

          if (!valid) {
            success.classList.remove("show");
            form.reportValidity();
            return;
          }

          success.classList.add("show");
        });

        form.addEventListener("input", (event) => {
          const target = event.target;
          if (!(target instanceof HTMLInputElement)) return;
          state.values[target.name] = target.value;
          if (state.submitted) renderFields();
        });

        form.append(
          fields,
          h(
            "div",
            { className: "actions" },
            h("button", { type: "submit", textContent: "Send message" })
          ),
          success
        );

        return form;
      }

      function App() {
        return h(
          "main",
          { className: "card" },
          h(
            "section",
            { className: "hero" },
            h("p", { className: "eyebrow", textContent: "Support" }),
            h("h1", { textContent: "Contact our team" }),
            h(
              "p",
              {
                className: "subtitle",
                textContent:
                  "Send us your details and we’ll get back to you as soon as possible. Required fields are clearly marked, and phone number is optional.",
              }
            )
          ),
          ContactForm()
        );
      }

      document.getElementById("app").appendChild(App());
    </script>
  </body>
</html>
